 static int count;
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}
 static void Reject(Action a,string label){try{a();}catch{Check(true,label);return;}throw new Exception(label);}
 static readonly DateTime Now=new DateTime(2026,10,29,12,0,0,DateTimeKind.Utc);
 static JObject Product(string id="offer",string title="Fixture Game")=>JObject.Parse("{id:'"+id+"',title:'"+title+"',namespace:'ns',offerType:'BASE_GAME',productSlug:null,urlSlug:'internal-id',catalogNs:{mappings:[{pageSlug:'fixture-game',pageType:'productHome'}]},offerMappings:[{pageSlug:'fixture-edition',pageType:'productHome'}],price:{totalPrice:{originalPrice:1319900,discountPrice:395970,currencyCode:'KZT',currencyInfo:{decimals:2}},lineOffers:[{appliedRules:[{endDate:'2026-11-02T16:00:00Z'}]}]}}");
 static string SearchJson(params JObject[] items)=>new JObject{["data"]=new JObject{["Catalog"]=new JObject{["searchStore"]=new JObject{["elements"]=new JArray(items)}}}}.ToString();
 static string OfferJson(JObject p)=>new JObject{["data"]=new JObject{["Catalog"]=new JObject{["catalogOffer"]=p}}}.ToString();
 static JObject Mirror(string id="0123456789abcdef0123456789abcdef",string title="Fixture Game",string type="BASE_GAME",string slug="fixture-game")=>JObject.Parse("{id:'"+id+"',title:'"+title+"',namespace:'ns',offerType:'"+type+"',productSlug:'"+slug+"',lastModifiedDate:'2026-10-28T00:00:00Z',offerMappings:[{pageSlug:'"+slug+"',pageType:'"+(type=="EDITION"?"offer":"productHome")+"'}],price:{country:'KZ',region:'KZ',offerId:'"+id+"',namespace:'ns',updatedAt:'2026-10-28T00:00:00Z',price:{originalPrice:1319900,discountPrice:395970,currencyCode:'KZT'},appliedRules:[{endDate:'2026-11-02T16:00:00Z'}]}} ");
 static List<PriceProduct> Parse(JObject p,bool sales=false)=>PriceService.ParseEpicProducts(SearchJson(p),"KZ",Now,sales);
 sealed class Http:HttpMessageHandler {
  public readonly List<string> queries=new List<string>();public Func<string,string> answer;public bool offline,blockedEpic;public HttpStatusCode? epicStatus;public Func<Exception> epicFailure;
  protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct){ct.ThrowIfCancellationRequested();var u=Uri.UnescapeDataString(r.RequestUri.AbsoluteUri);lock(queries)queries.Add(u);var epic=u.Contains("store.epicgames.com/graphql");if(epic&&epicFailure!=null)throw epicFailure();var status=epic&&epicStatus.HasValue?epicStatus.Value:blockedEpic&&epic?HttpStatusCode.Forbidden:offline?HttpStatusCode.ServiceUnavailable:HttpStatusCode.OK;return Task.FromResult(new HttpResponseMessage(status){Content=new StringContent(answer?.Invoke(u)??"{}")});}
 }
 static string Fx()=>"<ValCurs Date='"+DateTime.UtcNow.ToString("dd.MM.yyyy")+"'><Valute><CharCode>KZT</CharCode><Nominal>100</Nominal><Value>20</Value></Valute></ValCurs>";
 static JObject Current(JObject p=null){p=p??Product();p["price"]["lineOffers"][0]["appliedRules"][0]["endDate"]=DateTime.UtcNow.AddDays(7).ToString("O");return p;}
 static JObject CurrentMirror(){var p=Mirror();p["price"]["appliedRules"][0]["endDate"]=DateTime.UtcNow.AddDays(7).ToString("O");return p;}
 static JObject Platform(string display="KZT 13,199.00")=>JObject.Parse("{__typename:'Offer',id:'offer',store:'EGS',productId:'product',title:'Fixture Game',mapping:{__typename:'InternalMapping',slug:'fixture-edition'},tags:{platforms:[{id:'9547',name:'Windows'}]},purchase:[{status:'AvailableToPurchase',offerLifecycleState:'Release',priceDisplay:'"+display+"',purchaseStateEffectiveDate:1700000000000,purchasePayload:{offerId:'offer',sandboxId:'ns'}}]}");
 static string MirrorAnswer(string u)=>u.Contains("/search/v2/search")?new JObject{["offers"]=new JArray(CurrentMirror())}.ToString():u.Contains("/offers/0123456789abcdef0123456789abcdef/price")?CurrentMirror()["price"].ToString():u.Contains("/offers/0123456789abcdef0123456789abcdef")?CurrentMirror().ToString():Answer(u);
 static string Answer(string u,JObject exact=null)=>u.Contains("www.cbr.ru")?Fx():u.Contains("catalogOffer")?OfferJson(Current(exact)):u.Contains("graphql")?SearchJson(Current()):u.Contains("freeGamesPromotions")?SearchJson():u.Contains("catalog.gog.com")?"{products:[]}":u.Contains("storesearch")?"{items:[]}":u.Contains("plati.io")?"{items:[]}":"<html></html>";
