   var account=Settings().Account("epic");var found=await service.Search("epic","Cyberpunk 2077",account,true,CancellationToken.None);var exact=found.products.Single(p2=>p2.name=="Cyberpunk 2077");Check(exact.preview?.amount>0&&exact.preview.provider=="Epic"&&exact.url.EndsWith("/cyberpunk-2077"),"live Epic search quote and base-game link");var edition=found.products.Single(p2=>p2.name=="Cyberpunk 2077: Ultimate Edition");Check(edition.preview?.amount>0&&edition.preview.provider=="Epic"&&edition.url.EndsWith("/cyberpunk-2077--ultimate-edition"),"live edition quote and exact page link");var hades=await service.Search("epic","Hades",account,true,CancellationToken.None);Check(hades.products.Any(p2=>p2.name=="Hades"&&p2.preview?.amount>0&&p2.url.EndsWith("/hades")),"live Hades quote and link");var deals=await service.Discover("epic",account,true,CancellationToken.None);Check(deals.status=="ok"&&deals.products.Count>0,"live Epic sale feed");var report=await service.Compare(exact,Settings(),true,CancellationToken.None);Check(report.sources.First().match=="id"&&report.sources.First().offers.Count==1,"live exact Epic quote");var fromSteam=await service.Compare(new PriceProduct{store="steam",id="1091500",name="Cyberpunk 2077"},Settings(),true,CancellationToken.None);Check(fromSteam.sources.Single(s=>s.source=="epic").offers.Any(o=>o.amount>0&&o.url.EndsWith("/cyberpunk-2077")),"live Steam game comparison includes Epic price and exact link");Console.WriteLine("LIVE Epic: "+exact.preview.amount+" "+exact.preview.currency+"; deals="+deals.products.Count+"; checked="+deals.checkedAt+"; FX="+found.fxDate);
  }}
